-- Ensure the unique constraint exists (drop old name first if present)
ALTER TABLE hl7_fhir_templates
    DROP CONSTRAINT IF EXISTS unique_default_template;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'unique_default_template_v2'
          AND conrelid = 'hl7_fhir_templates'::regclass
    ) THEN
        ALTER TABLE hl7_fhir_templates
            ADD CONSTRAINT unique_default_template_v2
                UNIQUE (message_type, hl7_version, is_default);
    END IF;
END $$;

